// from src/locales/ja/blog.ts. Body + FAQs for article 'how-to-adjust-image-saturation' (ja).
// This file is the single source for this article's ja body text.
import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>彩度を調整するのは、数分で終わる簡単な作業です。写真をアップロードしてスライダーを動かし、色を確認して、より鮮やかなバージョンをダウンロードするだけです。</p>\n<p>この記事では、その手順を最初から最後まで解説します。スライダー、プリセット、肌色、色を自然に保つ書き出し設定までカバーします。</p>\n<p>読み終わるころには、くすんだ風景も、わざとらしい写真も、カラーのポートレートをきれいな白黒にする作業も、どのデバイスでもできるようになります。仕上がりを確認するまで、元の写真は残しておきましょう。</p>\n<h2 id=\"before-you-start\">始める前に：色の状態を見極める</h2>\n<p>ツールを開く前に、写真をよく見ましょう。色はくすんでいるか、鮮やかか、わざとらしいか。その答えで、スライダーをどちらに動かすか決まります。</p>\n<p>くすんだ写真は10〜25%のプラスの追加が必要です。わざとらしい写真は、マイナスの動きで色を自然なほうに戻します。</p>\n<p>写真が暗すぎたり平たすぎたりしていないかも確認します。くすんで暗い写真はまず明るさが必要です。彩度だけではレベルは直りません。</p>\n<p><a href=\"/ja/saido-chosei/\">画像彩度調整ツール</a>をブラウザで開きます。処理はすべて端末の中で行われるので、写真がサーバーにアップロードされることはありません。</p>\n<h2 id=\"step-by-step\">彩度を調整する5ステップ</h2>\n<p>写真でもスクリーンショットでも、スキャンした画像でも、手順は同じです。アップロード、調整、色の確認、書き出し、ダウンロードの確認の5つです。</p>\n<p>スライダーの操作には時間をかけましょう。小さな動きでも大きな違いが出るので、プレビューを見ながら、色がちょうどいいところで止めます。</p>\n<ol>\n<li>画像をドロップゾーンにドラッグするか、デバイスから選ぶか、Ctrl+Vでスクリーンショットを貼り付けてアップロードします。</li>\n<li>「彩度レベル」スライダーを右に動かして色を強く、左に動かして色をくすませ、ライブプレビューを見ながら調整します。</li>\n<li>ミュート、グレースケール、ハイパーなどのプリセットをワンクリックで試し、そこからスライダーで微調整します。</li>\n<li>肌色や葉、空を実物大で確認し、どの色も人工的に見えないか見ます。</li>\n<li>書き出し形式と画質を選び、ダウンロードをクリックして保存します。</li>\n</ol>\n<p>ダウンロードしたファイルは、使う前に一度開いて確認しましょう。色が自然で鮮やかに見え、ネオンになったりオレンジになったりしていないか見ます。</p>\n<h2 id=\"using-the-slider\">彩度スライダーの使い方</h2>\n<p>スライダーは-100%から+100%まで動き、0が変化なしです。右に動かすと色が強くなり、左に動かすと色が抜けます。</p>\n<p>ゆっくりドラッグして、プレビューを見ましょう。ライブ表示で色の反応がそのまま見えるので、自然に見える所で止められます。</p>\n<p>大きな動きより小さな動きがいいです。10〜25%の変化で十分なことが多く、それ以上大きく動かすと色がすぐ人工的に見えます。</p>\n<p>このツールは、アップロード直後に写真を+25%でプレビューします。この出発点から、中くらいの彩度の追加がどんな感じかすぐわかります。</p>\n<h2 id=\"using-quick-presets\">プリセットを使う</h2>\n<p>ツールには、よく使う彩度の値をワンクリックで適用できるプリセットがあります。スライダーをドラッグせずに、いろいろな見た目をすばやく試せます。</p>\n<p>-40%のミュートは、色を穏やかで上品な見た目にやわらげます。-100%のグレースケールは、すべての色を取り除き白黒にします。</p>\n<p>+90%のハイパーは、色を限界まで押し上げます。ポスターやスタイル化したグラフィックには合いますが、自然な写真にはほとんど合いません。</p>\n<p>プリセットをクリックしてプレビューを見ます。近いけれど少し違うなら、そこからスライダーで微調整します。</p>\n<h2 id=\"boosting-a-dull-photo\">くすんだ写真を鮮やかにする</h2>\n<p>くすんだ写真をアップロードして、スライダーを+20%にします。プレビューを確認します。色が濃くなり、緑が深くなり、空が青くなって、わざとらしく見えなければOKです。</p>\n<p>まだくすんでいるときは、5%ずつ少しずつ上げます。1ステップごとに少し鮮やかになり、プレビューで止めるタイミングがわかります。</p>\n<p>上げながら葉を見ましょう。草や葉が先にネオンのように変わり、光る緑の野原がある風景は人工的に見えます。</p>\n<p>追加したあとわざとらしく見えたら、スライダーを5%下げます。小さな下げ幅でも、鮮やかさを失わずに自然な見た目が戻ることが多いです。</p>\n<h2 id=\"muting-a-harsh-photo\">わざとらしい写真をくすませる</h2>\n<p>色が強すぎる写真は、スライダーを左に動かします。-20%や-40%のようなマイナスの値で、色合いが穏やかな見た目にやわらぎます。</p>\n<p>くすませながら肌を確認します。顔は自然でやわらかく見えるべきで、グレーで生気がなくなってはいけません。色が完全に消える前に止めましょう。</p>\n<p>くすませるのは、結婚式やポートレート、ファインアートに合います。色がやわらかい写真は上品に見えますが、わざとらしい写真はうるさく見えます。</p>\n<p>完全に彩度をなくすには、-100%のグレースケールプリセットを使います。画像は白黒になり、ドラマチックなシーンや時代を超えたポートレートに合います。</p>\n<h2 id=\"converting-to-grayscale\">ワンクリックでグレースケールにする</h2>\n<p>グレースケールのプリセットをクリックすると、ワンステップですべての色が取り除かれます。画像は白黒になり、明るさとコントラストだけが残ります。</p>\n<p>グレースケールは、ドラマチックなシーンや建築、ストリート写真に合います。色より形と光が大事なときに使います。表情の強いポートレートにも合います。</p>\n<p>変換したあと、コントラストを確認します。グレースケールの写真は、色が担っていた深みがなくなった分、小さなコントラストの追加が必要なことが多いです。</p>\n<p>グレースケールの写真は、高画質設定のJPGで書き出すか、最もシャープに仕上げたいならPNGで書き出します。形式より大事なのはコントラストで、白黒の見た目を決めます。</p>\n<h2 id=\"fixing-skin-tones\">肌色を直す</h2>\n<p>肌は、彩度を正しく調整するのが最もむずかしい部分です。小さな追加でポートレートは健康的に見えますが、大きくすると肌がオレンジや赤、黄色になります。</p>\n<p>ポートレートは10〜15%の小さな追加から始めます。顔を確認します。肌はあたたかく自然に見えるべきで、日焼けしすぎたようになってはいけません。</p>\n<p>頬と額は、彩度の上げすぎが最初に出る場所です。頬がオレンジで額が黄色い顔は、上げすぎています。</p>\n<p>追加したあと肌がオレンジに見えたら、スライダーを5%下げてまた確認します。小さな下げ幅でも、健康的なツヤを失わずに自然なトーンが戻ることが多いです。</p>\n<h2 id=\"previewing\">ダウンロード前にプレビューする</h2>\n<p>ダウンロード前には必ずプレビューします。色が自然に見えるか、どこかがネオンになっていないか、肌色がオレンジではなくあたたかいかを確認します。</p>\n<p>実物大で葉や空、肌にズームします。彩度の上げすぎはこれらの部分に最初に出るので、小さいプレビューでは問題が隠れることがあります。</p>\n<p>できれば別の画面でも写真を確認します。色は画面によって違って見えるので、2回目の確認で共有する前に思わぬ違いに気づけます。</p>\n<p>どの色かが人工的に見えたら、スライダーを5%下げてまた確認します。小さな下げ幅でも、鮮やかさを失わずに自然な見た目が戻ることが多いです。</p>\n<h2 id=\"choosing-export-format\">書き出し形式を選ぶ</h2>\n<p>共有する写真にはJPGを選びます。ファイルサイズが小さく、どこでも使えて、高画質設定なら色もきれいに残ります。</p>\n<p>透明のあるグラフィックやステッカーにはPNGを選びます。PNGは可逆圧縮なので色が正確に残り、透けた部分も保てます。</p>\n<p>ファイルサイズを小さくしつつ画質を保ちたいならWebPです。Web用の画像に合いますが、古いシステムでは対応していない場合があります。</p>\n<p>PNGでは画質スライダーが表示されないのは正常です。PNGは可逆圧縮で画質設定がないためで、ツールの不具合ではありません。</p>\n<h2 id=\"adjusting-on-mobile\">スマホ・タブレットで彩度を調整する</h2>\n<p>このツールはタッチ画面でも使えます。撮ったその場でスマホからくすんだ写真を直せます。ギャラリーからアップロードし、スライダーを指でドラッグしてダウンロードします。</p>\n<p>指でのスライダー操作はマウスより精密ではありません。正確な値にはプリセットを使い、そこから小さくドラッグして微調整します。</p>\n<p>ダウンロード前に、プレビューを実物大で確認してください。スマホの小さい画面ではちょうどよく見えた彩度が、パソコンでは強すぎることがあります。</p>\n<p>ダウンロードしたファイルは、いつものダウンロードフォルダに保存されます。そこからチャットアプリやメール、SNS投稿に直接共有できます。</p>\n<h2 id=\"troubleshooting\">よくあるトラブルと対処法</h2>\n<p>写真がわざとらしく見えるときは、スライダーが高すぎます。少しずつ下げて、草や空、肌が自然に見えるまで調整します。</p>\n<p>追加してもまだくすんでいるときは、元の写真が平たすぎて救えない可能性があります。濃い霧を通して撮った写真は、撮れていない色を取り戻せません。</p>\n<p>肌がオレンジに見えるときは、彩度を下げて顔を実物大で確認します。小さな下げ幅でも、自然なトーンが戻ることが多いです。</p>\n<p>プレビューとダウンロード結果が違うときは、書き出し形式と画質を確認します。低画質のJPG設定では、色が少しずれることがあります。特に明るい部分で目立ちます。</p>\n<h2 id=\"saturation-plus-contrast\">彩度＋コントラストの定番ペア</h2>\n<p>くすんで平たい写真は、彩度とコントラストの両方が必要です。まず色を足し、次にコントラストを足して深みを戻します。</p>\n<p>彩度を足したあと画像が鮮やかだけれどまだ平たく見えるときは、<a href=\"/ja/kontrasuto-chosei/\">画像コントラスト調整ツール</a>を使います。小さなコントラストの追加で、シャドウとハイライトが戻ります。</p>\n<p>順番は彩度が先、コントラストがあとです。順番を逆にすると、画像がまだ平たい状態で色の変化を判断することになり、むずかしくなります。</p>\n<p>各ステップのあとに色を確認します。コントラストの追加でも色が濃くなるので、そのあと彩度を少し下げる必要があるかもしれません。</p>\n<h2 id=\"saturation-for-social\">SNS用の彩度</h2>\n<p>SNSのフィードでは、鮮やかではっきりした写真が好まれます。くすんだ写真はスクロールで通り過ぎられますが、よく彩度を上げた写真は指を止めてもう一度見てもらえます。</p>\n<p>SNS用の写真は、印刷用より少し鮮やかめにします。画面の色は人によって違い、自分のスマホでちょうどよく見えた写真が、ほかの人の画面ではくすんで見えることがあります。</p>\n<p>追加するのは自然な範囲で。上げすぎた写真は人工的に見え、フォロワーには色がシーンと合っていないことが伝わります。</p>\n<p>投稿前に、フィードのサイズでテストしましょう。実物大ではよく見えた写真も、小さいプレビューではくすみすぎたりわざとらしく見えたりすることがあるので、投稿前に確認します。</p>\n<h2 id=\"saving-settings\">設定をメモして次回に活かす</h2>\n<p>似た写真のセットでうまくいった彩度の値をメモしておきましょう。「風景は+20%」のような短いメモが、次回の迷いをなくします。</p>\n<p>同じ光で撮った写真のまとまりには、すべて同じ値を使います。色がそろったセットはプロっぽく見えますが、バラバラだと雑な印象になります。</p>\n<p>元のファイルは残しておきましょう。ある写真に合った彩度の値が、別の写真に合うとは限らず、元ファイルがあれば劣化なしで別の値を試せます。</p>\n<p>メモはときどき見直します。カメラや照明がよくなると、必要な彩度の値も変わるので、古いメモはかえって迷わせることがあります。</p>\n<h2 id=\"quick-tips\">彩度をきれいにするコツ</h2>\n<p>小さなステップで調整します。5%ずつの変化ならコントロールしやすく、大きなジャンプでは気づかないうちにちょうどいい値を飛び越えます。</p>\n<p>景色だけでなく肌も確認します。草にはよく見えた風景の追加が、写真の中の人をオレンジにすることがあります。</p>\n<p>プリセットは出発点として使います。プリセットですばやくテストし、スライダーでそこから微調整します。</p>\n<p>編集前の元写真は保存しておきましょう。彩度の変更を書き出すと元に戻せないので、元ファイルが唯一のきれいなコピーです。</p>\n<h2 id=\"saturation-for-sunset\">夕日の写真の彩度を調整する</h2>\n<p>夕日の写真はすでにカラフルなので、小さな追加だけで十分です。10〜15%の彩度の追加で、オレンジやピンクが深くなり、空が塗ったようにはなりません。</p>\n<p>追加しながら、空のグラデーションを見ましょう。夕日の空はオレンジからピンク、青へとなめらかに変わるべきで、強い追加ではグラデーションが平たい色のブロックになります。</p>\n<p>追加したあと、前景を確認します。暗い前景に色を足すとくすんで見えることがあるので、夕日が主役なら、まず前景を少し明るくします。</p>\n<p>水面に映る夕日では、中くらいの追加で反射が強くなり、わざとらしくなりません。水面は空を映すべきで、空と競ってはいけません。</p>\n<p>比較記事は<a href=\"/ja/blog/saido-vs-baiburansu/\">彩度とビブランスの違い</a>、全体の解説は<a href=\"/ja/blog/saido-chosei-kanzen-gaido/\">画像の彩度調整 完全ガイド</a>をご覧ください。写真全体に統一感のある見た目をつけるなら<a href=\"/ja/gazo-firuta/\">画像フィルターツール</a>をお試しください。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"スマホで写真の色を鮮やかにするにはどうすればいいですか？","answer":"スマホのブラウザで画像彩度調整ツールを開き、ギャラリーから写真をアップロードして、スライダーを右に指でドラッグします。正確な値にはプリセットを使い、肌色を確認してからダウンロードします。"},{"question":"風景写真にはどのくらいの彩度がいいですか？","answer":"まず+20%から始め、葉を確認します。風景はたいてい20〜30%で鮮やかに感じられます。草がネオンになったり空が塗ったように見えたりする前に止め、色が人工的に見えたらスライダーを下げましょう。"},{"question":"カラー写真を白黒にするにはどうすればいいですか？","answer":"グレースケールのプリセットをクリックします。彩度が-100%になり、ワンステップですべての色が取り除かれます。変換したあとはコントラストを確認しましょう。グレースケールの写真は、色が担っていた深みを補うために小さなコントラストの追加が必要なことが多いです。"},{"question":"彩度を上げたら食べ物写真がわざとらしく見えるのはなぜですか？","answer":"スライダーが高すぎて、赤が不自然に明るくなり、緑がネオンになっています。食べ物には10〜20%の小さな追加だけで十分です。料理が新鮮でおいしそうに見えるまで、スライダーを下げましょう。"},{"question":"彩度とコントラストはどちらを先に調整しますか？","answer":"彩度が先、コントラストがあとです。色を足すと画像の感じが変わるので、そのあとコントラストで深みを整えます。コントラストの変更でも色が濃くなるので、そのあと色をもう一度確認しましょう。"},{"question":"ダウンロードしたあと、彩度の変更を元に戻せますか？","answer":"ダウンロードしたファイルからは戻せません。変更は書き出しに固定されるからです。元の写真を残しておけば、別の彩度の値を試せます。ツール内では、ダウンロード前にリセットすれば0に戻ります。"}];
